class AltSensor:   # fremde Bibliothek
    def lies_fahrenheit(self):
        return 77.0

class SensorAdapter:
    def __init__(self, alt):
        self.alt = alt
    def celsius(self):
        f = self.alt.lies_fahrenheit()
        return (f - 32) * 5 / 9

def anzeigen(sensor):
    print(f"{sensor.celsius():.1f} °C")

anzeigen(SensorAdapter(AltSensor()))
# 25.0 °C

class Kaffee:
    def preis(self):
        return 2.50
    def text(self):
        return "Kaffee"

class Extra:
    def __init__(self, inner):
        self.inner = inner

class Milch(Extra):
    def preis(self):
        return self.inner.preis() + 0.40
    def text(self):
        return self.inner.text() + " + Milch"

class Sirup(Extra):
    def preis(self):
        return self.inner.preis() + 0.60
    def text(self):
        return self.inner.text() + " + Sirup"

k = Sirup(Milch(Milch(Kaffee())))
print(k.text())
print(f"{k.preis():.2f} €")
# Kaffee + Milch + Milch + Sirup
# 3.90 €

class Notenbuch:
    def __init__(self):
        self.beobachter = []
    def anmelden(self, f):
        self.beobachter.append(f)
    def eintragen(self, name, note):
        for f in self.beobachter:
            f(name, note)

def eltern_app(name, note):
    print(f"Push: {name} hat eine {note}")

def warnung(name, note):
    if note == 5:
        print(f"Frühwarnung für {name}!")

nb = Notenbuch()
nb.anmelden(eltern_app)
nb.anmelden(warnung)
nb.eintragen("Ana", 2)
nb.eintragen("Ben", 5)
# Push: Ana hat eine 2
# Push: Ben hat eine 5
# Frühwarnung für Ben!

def standard(kg):
    return 4.90

def express(kg):
    return 9.90 + 0.5 * kg

def abholung(kg):
    return 0.0

class Bestellung:
    def __init__(self, kg, versand):
        self.kg = kg
        self.versand = versand
    def kosten(self):
        return self.versand(self.kg)

b = Bestellung(4, express)
print(b.kosten())   # 11.9
b.versand = abholung
print(b.kosten())   # 0.0

